/**
 * Conversation titles (#214): one per conversation, in the conversation store
 * next to the verbatim archive (`./verbatim-archive-store.ts`) whose
 * conversations they name, so a title lives and goes with the archive. A title is either
 * generated by the model after the person's first turn
 * (`../session/conversation-titler.ts`) or chosen by the person
 * (`../identity/channel-conversations.ts`), and the person's is never
 * replaced by a generated one.
 */
import type { ConversationStore } from "@mercury-fw/channel-types";

/** Who gave a conversation its title: the model, or the person. */
export type TitleSource = "generated" | "person";

/** A conversation's title and who gave it. */
export type ConversationTitle = { title: string; source: TitleSource };

/** The longest a title can be, in characters. */
export const MAX_TITLE_LENGTH = 100;

/** Line breaks and other control characters, which a title can't hold. */
const CONTROL = /[\u0000-\u001f\u007f\u0085\u2028\u2029]/;

/** Pairs of quotes a model wraps a title in. */
const WRAPPING_QUOTES: Array<[string, string]> = [
  ['"', '"'],
  ["'", "'"],
  ["“", "”"],
  ["‘", "’"],
  ["«", "»"],
  ["`", "`"],
];

/** Strips one pair of quotes wrapped around `text`, if any. */
function unwrapQuotes(text: string): string {
  for (const [open, close] of WRAPPING_QUOTES) {
    if (text.length >= open.length + close.length && text.startsWith(open) && text.endsWith(close)) {
      return text.slice(open.length, text.length - close.length).trim();
    }
  }
  return text;
}

/**
 * What a model answered, as a title: its first non-empty line without the
 * dressing a model adds (a `Title:` label, Markdown marks, wrapping quotes, a
 * trailing period or colon, control characters), cut on a word boundary with
 * an ellipsis when longer than `MAX_TITLE_LENGTH`. Empty when nothing is left.
 */
export function cleanGeneratedTitle(raw: string): string {
  const line = raw.split(/\r?\n|[\u0085\u2028\u2029]/).find((l) => l.trim() !== "") ?? "";
  let text = line.replace(/[\u0000-\u001f\u007f]/g, "").trim();
  text = text.replace(/^#+\s+/, "").replace(/^(title|titolo)\s*:\s*/i, "");
  text = text.replace(/\*\*|__|\*|`/g, "").trim();
  let previous: string;
  do {
    previous = text;
    text = unwrapQuotes(text);
  } while (text !== previous);
  text = text.replace(/[.:]+$/, "").trim();
  if (text.length <= MAX_TITLE_LENGTH) return text;
  const room = text.slice(0, MAX_TITLE_LENGTH - 1);
  const lastSpace = room.lastIndexOf(" ");
  const cut = lastSpace > 0 ? room.slice(0, lastSpace) : room;
  return `${cut.trimEnd()}…`;
}

/** Why `title` (already trimmed) can't be a conversation's title, or undefined when it can. */
export function titleError(title: string): string | undefined {
  if (title.length === 0) return "the title is empty";
  if (title.length > MAX_TITLE_LENGTH) return `the title is longer than ${MAX_TITLE_LENGTH} characters`;
  if (CONTROL.test(title)) return "the title has a line break or another control character";
  return undefined;
}

/** Saves `entry` as the title of the person's conversation, in place of the one it had. */
export async function setTitle(
  store: ConversationStore,
  entry: { userId: string; sessionKey: string; title: string; source: TitleSource },
  now: () => Date = () => new Date(),
): Promise<void> {
  await store.setTitle({ ...entry, updatedAt: now().toISOString() });
}

/** The stored title in `payload`, or undefined when it's malformed. */
function storedTitle(payload: Record<string, unknown> | null | undefined): (ConversationTitle & { sessionKey: string }) | undefined {
  if (
    payload == null ||
    typeof payload.sessionKey !== "string" ||
    typeof payload.title !== "string" ||
    (payload.source !== "generated" && payload.source !== "person")
  ) {
    return undefined;
  }
  return { sessionKey: payload.sessionKey, title: payload.title, source: payload.source };
}

/** The titles of `sessionKeys` for `userId`, by session key; a conversation with none is missing. */
export async function titlesOf(
  store: ConversationStore,
  query: { userId: string; sessionKeys: string[] },
): Promise<Map<string, ConversationTitle>> {
  const titles = new Map<string, ConversationTitle>();
  if (query.sessionKeys.length === 0) return titles;
  for (const stored of await store.titles(query)) {
    const title = storedTitle(stored);
    if (title !== undefined) titles.set(title.sessionKey, { title: title.title, source: title.source });
  }
  return titles;
}

/** The title of `sessionKey` for `userId`, or undefined when it has none. */
export async function titleOf(
  store: ConversationStore,
  query: { userId: string; sessionKey: string },
): Promise<ConversationTitle | undefined> {
  return (await titlesOf(store, { userId: query.userId, sessionKeys: [query.sessionKey] })).get(query.sessionKey);
}
